def transform(grid):
    from collections import deque
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                touches_edge |= y == 0 or x == 0 or y == h - 1 or x == w - 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == background and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not touches_edge:
                color = 2 if len(cells) in (4, 16) else 7
                for y, x in cells:
                    out[y][x] = color
    return out
